import math
from itertools import permutations

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def sigma(n):
    return sum(get_divisors(n))

def is_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def solve_for_m(m):
    divisors = get_divisors(m)
    sum_div = sigma(m)
    n = len(divisors)

    if not is_square(sum_div):
        return {"m": m, "divisors": divisors, "sigma(m)": sum_div, "result": "Sigma(m) is not a perfect square."}

    # If sigma(m) is a perfect square, we must attempt to find a permutation.
    # Since n is small (at most 6 for m<=15), we can attempt checking permutations.
    # For m=12, divisors are {1, 2, 3, 4, 6, 12}, n=6. 6! = 720. Manageable.

    found = False
    for p in permutations(divisors):
        current_sum = 0
        all_prefix_sums_square = True
        for i in range(n):
            current_sum += p[i]
            if not is_square(current_sum):
                all_prefix_sums_square = False
                break

        if all_prefix_sums_square:
            found = True
            break

    result_str = "Found permutation" if found else "No permutation found"

    return {"m": m, "divisors": divisors, "sigma(m)": sum_div, "result": result_str}

results = []
for m in range(2, 16):
    results.append(solve_for_m(m))

for r in results:
    print(f"m={r['m']}: sigma={r['sigma(m)']}, result={r['result']}")
    if r['result'] == "Found permutation":
        print(f"  Divisors: {r['divisors']}")

