from itertools import permutations

def check_permutation(divisors):
    """Checks if any permutation of divisors results in all prefix sums being perfect squares."""

    # Helper function to check if a number is a perfect square
    def is_square(n):
        if n < 0:
            return False
        root = int(n**0.5)
        return root * root == n

    # Iterate through all permutations
    for p in permutations(divisors):
        current_sum = 0
        prefix_sums_are_squares = True

        for i, divisor in enumerate(p):
            current_sum += divisor
            if not is_square(current_sum):
                prefix_sums_are_squares = False
                break

        if prefix_sums_are_squares:
            return True, p

    return False, None

